#!/usr/bin/env bash
set -euo pipefail
theme_menu(){ while true; do ui_section 'ZxvCode / THEME STUDIO'; printf '  [01] ZxvCode Midnight\n  [02] ZxvCode Neon\n  [03] ZxvCode Minimal\n  [04] Backup panel resources\n  [05] Build production assets\n  [00] Back\n\n'; read -r -p '  Select theme › ' t; case "$t" in 1)install_theme zxvcode-midnight;;2)install_theme zxvcode-neon;;3)install_theme zxvcode-minimal;;4)backup_theme;;5)build_theme;;0|00)return;;*)ui_warning 'Unknown option.';;esac; done; }
install_theme(){ local name=$1 panel="${PTERODACTYL_DIRECTORY:-/var/www/pterodactyl}"; [[ -d $panel ]]|| { ui_error 'Panel not found.';return 1; }; mkdir -p "$panel/public/zxvcode-themes/$name"; cp -a "$(cd "$(dirname "${BASH_SOURCE[0]}")/../themes/$name"&&pwd)/." "$panel/public/zxvcode-themes/$name/"; ui_success "Theme asset $name installed."; ui_warning 'Applying a full React theme requires a panel-compatible frontend build or supported theme/extension mechanism.'; }
backup_theme(){ local panel="${PTERODACTYL_DIRECTORY:-/var/www/pterodactyl}" out="/root/zxvcode-theme-$(date +%Y%m%d-%H%M%S).tar.gz"; tar -czf "$out" -C "$panel" resources public 2>/dev/null|| { ui_error 'Backup failed.';return 1; }; ui_success "Backup: $out"; }
build_theme(){ local panel="${PTERODACTYL_DIRECTORY:-/var/www/pterodactyl}"; [[ -d $panel ]]|| { ui_error 'Panel not found.';return 1; }; cd "$panel"; command -v yarn >/dev/null 2>&1||npm install -g yarn; yarn build:production; ui_success 'Production assets rebuilt.'; }
